def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered paths of K moves through distinct empty grid cells.

    Each move goes up, down, left, or right. Paths may start at any
    empty cell; a path and its reversal are counted separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        neighbors.append([
            indices[(nr, nc)]
            for nr, nc in ((r - 1, c), (r + 1, c),
                           (r, c - 1), (r, c + 1))
            if (nr, nc) in indices
        ])

    visited = [False] * len(cells)

    def search(cell, remaining):
        if remaining == 0:
            return 1
        visited[cell] = True
        total = 0
        for neighbor in neighbors[cell]:
            if not visited[neighbor]:
                total += search(neighbor, remaining - 1)
        visited[cell] = False
        return total

    return sum(search(start, K) for start in range(len(cells)))

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a grid can be covered exactly by a subset of the tiles.

    Each tile can be rotated, must align with cells, and may be used at most
    once. Tiles may remain unused. Grid dimensions are at most 10 and there
    are at most 7 tiles.
    """
    # Discard tiles that cannot fit in either orientation. Canonical dimensions
    # also let the search avoid equivalent choices of identical tiles.
    shapes = []
    for a, b in tiles[:n]:
        a, b = sorted((a, b))
        if (a <= h and b <= w) or (b <= h and a <= w):
            shapes.append((a, b))
    shapes.sort(key=lambda shape: shape[0] * shape[1], reverse=True)
    count = len(shapes)
    areas = [a * b for a, b in shapes]
    orientations = []
    for a, b in shapes:
        choices = []
        for height, width in sorted({(a, b), (b, a)}):
            if height <= h and width <= w:
                mask = sum(((1 << width) - 1) << (row * w)
                           for row in range(height))
                choices.append((height, width, mask))
        orientations.append(choices)

    # Bit k records whether some subset of the remaining tiles has area k.
    subset_areas = [1] * (1 << count)
    for remaining in range(1, 1 << count):
        bit = remaining & -remaining
        index = bit.bit_length() - 1
        smaller = subset_areas[remaining ^ bit]
        subset_areas[remaining] = smaller | (smaller << areas[index])

    full = (1 << (h * w)) - 1

    @lru_cache(None)
    def search(covered: int, remaining: int) -> bool:
        if covered == full:
            return True
        empty_area = h * w - covered.bit_count()
        if not ((subset_areas[remaining] >> empty_area) & 1):
            return False

        # The first uncovered cell must be the upper-left cell of the tile
        # covering it: extending above or left would overlap an earlier cell.
        empty = full ^ covered
        position = (empty & -empty).bit_length() - 1
        row, column = divmod(position, w)
        tried = set()
        for index, shape in enumerate(shapes):
            bit = 1 << index
            if not (remaining & bit) or shape in tried:
                continue
            tried.add(shape)
            for height, width, base_mask in orientations[index]:
                if row + height > h or column + width > w:
                    continue
                placement = base_mask << position
                if not (covered & placement):
                    if search(covered | placement, remaining ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can become t with at most k single-character edits.

    Allowed edits are insertion, deletion, and replacement. Strings may have
    up to 500000 characters, and the specified edit budget is at most 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True
    if k <= 0:
        return False
    if max(n, m) <= k:
        return True

    # On diagonal d = i - j, retain the furthest source position reachable
    # after each edit budget, extending every state through matching letters.
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    frontier = {0: i}
    for _ in range(k):
        candidates = {}
        for diagonal, i in frontier.items():
            j = i - diagonal
            if i < n:  # Delete s[i].
                d = diagonal + 1
                candidates[d] = max(candidates.get(d, -1), i + 1)
            if j < m:  # Insert t[j].
                d = diagonal - 1
                candidates[d] = max(candidates.get(d, -1), i)
            if i < n and j < m:  # Replace s[i] with t[j].
                candidates[diagonal] = max(
                    candidates.get(diagonal, -1), i + 1
                )

        frontier = {}
        for diagonal, i in candidates.items():
            j = i - diagonal
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            frontier[diagonal] = i
    return False

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k reducible contiguous substrings.

    A substring is reducible exactly when the parities of its three letter
    counts are equal. Encode A, B, C by 1, 2, 3: this is equivalent to XOR zero.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix XORs differ, so no value occurs more than
    # ceil((n+1)/2) times. Alternating two values maximizes equal pairs.
    if k > n * n // 4:
        return 0

    # Six bits per frequency (n <= 50), and two low bits for current XOR.
    # Keeping frequencies suffices: the answer is sum choose(freq, 2).
    increments = (1 << 2, 1 << 8, 1 << 14, 1 << 20)
    dp = {increments[0]: 1}  # Include the empty prefix with XOR zero.
    for ch in s:
        choices = (1, 2, 3) if ch == '?' else ('ABC'.index(ch) + 1,)
        nxt = {}
        for state, ways in dp.items():
            current = state & 3
            for letter in choices:
                target = current ^ letter
                new_state = (state & ~3) + increments[target] + target
                nxt[new_state] = (nxt.get(new_state, 0) + ways) % mod
        dp = nxt

    answer = 0
    for state, ways in dp.items():
        pairs = 0
        for shift in (2, 8, 14, 20):
            frequency = (state >> shift) & 63
            pairs += frequency * (frequency - 1) // 2
        if pairs >= k:
            answer += ways
    return answer % mod

from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(places: int, total: int, needed: int) -> int:
    """Count nonzero-digit suffixes with this sum and product requirement."""
    if total < places or total > 9 * places:
        return 0
    if places == 0:
        return int(total == 0 and needed == 1)
    return sum(
        _suffix_count(places - 1, total - digit, needed // gcd(needed, digit))
        for digit in range(max(1, total - 9 * (places - 1)),
                           min(9, total - (places - 1)) + 1)
    )


@lru_cache(maxsize=256)
def _beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    size = len(digits)

    # Every number containing a zero has product zero and positive digit sum.
    nonzero = sum(9 ** length for length in range(1, size))
    for index, digit in enumerate(digits):
        nonzero += max(0, digit - 1) * 9 ** (size - index - 1)
        if digit == 0:
            break
    else:
        nonzero += 1
    answer = bound - nonzero

    # A product of nonzero decimal digits has only prime factors 2, 3, 5, 7.
    for length in range(1, size + 1):
        for target in range(length, 9 * length + 1):
            residual = target
            for prime in (2, 3, 5, 7):
                while residual % prime == 0:
                    residual //= prime
            if residual != 1:
                continue
            if length < size:
                answer += _suffix_count(length, target, target)
                continue

            remaining_sum = target
            needed = target
            for index, digit in enumerate(digits):
                places = size - index - 1
                for smaller in range(1, digit):
                    answer += _suffix_count(
                        places, remaining_sum - smaller,
                        needed // gcd(needed, smaller)
                    )
                if digit == 0:
                    break
                remaining_sum -= digit
                needed //= gcd(needed, digit)
            else:
                answer += int(remaining_sum == 0 and needed == 1)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when the product of its digits is divisible by
    the sum of its digits.

    Args:
        l: Inclusive lower bound.
        r: Inclusive upper bound.

    Returns:
        The number of beautiful numbers in [l, r].

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _beautiful_up_to(r) - _beautiful_up_to(l - 1)

