from typing import List, Tuple
from functools import lru_cache


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether some of the available rectangles perfectly tile the grid.

    Each tile can be used at most once and may be rotated. All tiles are aligned
    to grid cells, cannot overlap, and cannot extend outside the h by w grid.
    """
    tiles = tiles[:n]
    n = len(tiles)
    total = h * w
    full = (1 << total) - 1
    areas = [a * b for a, b in tiles]

    # Possible total areas obtainable from every set of available tiles.
    sums = [0] * (1 << n)
    sums[0] = 1
    for mask in range(1, 1 << n):
        bit = mask & -mask
        i = bit.bit_length() - 1
        rest = sums[mask ^ bit]
        sums[mask] = rest | (rest << areas[i])

    placements = [[[] for _ in range(n)] for _ in range(total)]
    for cell in range(total):
        row, col = divmod(cell, w)
        for i, (a, b) in enumerate(tiles):
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    stripe = (1 << width) - 1
                    placement = 0
                    for r in range(row, row + height):
                        placement |= stripe << (r * w + col)
                    placements[cell][i].append(placement)

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True
        missing = total - occupied.bit_count()
        if not ((sums[available] >> missing) & 1):
            return False
        # In any completion, the tile covering the first empty cell must have
        # that cell as its upper-left corner.
        empty = full ^ occupied
        cell = (empty & -empty).bit_length() - 1
        tried = set()
        for i, (a, b) in enumerate(tiles):
            bit = 1 << i
            shape = (min(a, b), max(a, b))
            if not (available & bit) or shape in tried:
                continue
            tried.add(shape)
            for placement in placements[cell][i]:
                if not (occupied & placement):
                    if search(occupied | placement, available ^ bit):
                        return True
        return False

    return search(0, (1 << n) - 1)

